"""Generate the Colab notebook from reviewable cells, without stored outputs or secrets."""
import json
from pathlib import Path
cells=[]
def md(s):cells.append({"cell_type":"markdown","metadata":{},"source":s.splitlines(True)})
def code(s):cells.append({"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":s.splitlines(True)})
md("# ProbeForge 0.2 — Colab A100 pilot\nChoose an A100 runtime. This notebook installs the pinned training stack; restart the runtime after installation if prompted. Upload the release ZIP. No model training has been performed in this notebook. Save checkpoints to mounted Drive so runtime expiration does not erase them.")
code("from google.colab import drive, files\ndrive.mount('/content/drive')\nuploaded = files.upload()\nimport zipfile\narchive = next(name for name in uploaded if name.endswith('.zip'))\nwith zipfile.ZipFile(archive) as z:\n    z.extractall('/content')\n%cd /content/probeforge\n%pip install -e '.[train,quant,energy]'\n")
md("## Check environment and download\nModel files require disk space. If imports fail after dependency installation, restart the runtime and return to this directory.")
code("import torch\nassert torch.cuda.is_available(), 'Select a GPU runtime'\nprint(torch.cuda.get_device_name(0))\n!contrastforge doctor\n!contrastforge download --model Qwen/Qwen3-8B --out models/Qwen3-8B\n")
md("## Data pilot\n60 training worlds produce 1,600 training prompts. Use a fresh directory when changing the dataset. Natural-language templates need bilingual review before research claims.")
code("!contrastforge generate --out data/contrast --groups 60\n!contrastforge preflight --inputs data/contrast/train.jsonl data/contrast/validation.jsonl data/contrast/test.jsonl --tokenizer models/Qwen3-8B --max-length 2048\n")
code("!contrastforge collect --inputs data/contrast/train.jsonl data/contrast/validation.jsonl --out data/student_base.jsonl --model models/Qwen3-8B --quantize --budgets 512\n")
code("import subprocess, sys\nfor arm in ['translated', 'random', 'mined', 'no_counterfactual']:\n    subprocess.run([sys.executable, '-m', 'contrastforge.cli', 'prepare', '--inputs', 'data/contrast/train.jsonl', 'data/contrast/validation.jsonl', '--rollouts', 'data/student_base.jsonl', '--strategy', arm, '--tokenizer', 'models/Qwen3-8B', '--token-budget', '2000000', '--out', f'data/curricula/{arm}'], check=True)\n")
md("## Persist data and train\nUse a new experiment name for each run. Rerunning the same configuration needs `--resume latest` and an existing periodic checkpoint. A final adapter alone is not an optimizer checkpoint.")
code("from pathlib import Path\nimport json, shutil\nproject = Path('/content/drive/MyDrive/contrastforge_experiment_01')\nproject.mkdir(parents=True, exist_ok=True)\nshutil.copytree('data', project/'data', dirs_exist_ok=True)\ncfg = json.loads(Path('configs/contrast_sft_colab.json').read_text())\ncfg['train_data'] = str(project/'data/curricula/mined/sft_train.jsonl')\ncfg['validation_data'] = str(project/'data/curricula/mined/sft_validation.jsonl')\ncfg['output_dir'] = str(project/'sft_adapter')\nPath('configs/colab_active.json').write_text(json.dumps(cfg, indent=2))\nsubprocess.run([sys.executable, '-m', 'contrastforge.cli', 'train', '--config', 'configs/colab_active.json'], check=True)\n")
md("## Matched held-out evaluation\nEvaluate the base and the adapter with identical prompts, budgets and quantization. These results measure this generated benchmark; add external retention tasks.")
code("for name, adapter in [('base', None), ('sft', str(project/'sft_adapter'))]:\n    command = [sys.executable, '-m', 'contrastforge.cli', 'collect', '--inputs', 'data/contrast/test.jsonl', '--out', str(project/f'{name}_test.jsonl'), '--model', 'models/Qwen3-8B', '--quantize', '--budgets', '256', '512', '1024']\n    if adapter: command += ['--adapter', adapter]\n    subprocess.run(command, check=True)\n    subprocess.run([sys.executable, '-m', 'contrastforge.cli', 'evaluate', '--inputs', 'data/contrast/test.jsonl', '--rollouts', str(project/f'{name}_test.jsonl'), '--out', str(project/f'{name}_report.json')], check=True)\nsubprocess.run([sys.executable, '-m', 'contrastforge.cli', 'compare', '--reports', str(project/'base_report.json'), str(project/'sft_report.json'), '--out', str(project/'comparison.json')], check=True)\nprint((project/'comparison.json').read_text())\n")
md("Optional DPO, teacher assistance, LIC and vision workflows are in `docs/CONTRAST_RUNBOOK.md`. Do not use `--allow-synthetic` for real experiments.")
for i,cell in enumerate(cells):cell["id"]=f"contrast_{i:02d}"
notebook={"nbformat":4,"nbformat_minor":5,"metadata":{"accelerator":"GPU","kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":cells}
path=Path(__file__).resolve().parents[1]/'notebooks/contrast_colab_a100.ipynb'
path.write_text(json.dumps(notebook,indent=2,ensure_ascii=False)+'\n')
print(path)
